mapper.insert:
INSERT HH_USER(
	UPDATE_DATE
	, ENABLED
	, ID 
	, PW 
	, NICKNAME 
	, BIRTHDAY
	, IMAGE  
	, PW_CHECK1 
	, PW_CHECK2 
	, PW_CHECK3 
) VALUES (
	DATETIME('NOW','LOCALTIME')
	, #{enabled, typeHandler=com.utime.household.common.handler.BooleanTypeHandler}
	, #{id}
	, LOWER(HEX(HASH(#{pw}))) 
	, #{nickName}
	, #{birthday}
	, #{imageBytes} 
	, #{pwCheck1} 
	, #{pwCheck2} 
	, #{pwCheck3} 
)

mapper.update:
UPDATE HH_USER SET
	UPDATE_DATE = DATETIME('NOW','LOCALTIME')
	, ENABLED = #{enabled, typeHandler=com.utime.household.common.handler.BooleanTypeHandler}
		, NICKNAME = #{nickName} 
		, IMAGE = #{imageBytes}  
	, PW_CHECK1 = #{pwCheck1}
	, PW_CHECK2 = #{pwCheck2}
	, PW_CHECK3 = #{pwCheck3}
WHERE NO = #{userNo}
